 function line(p,data,color,dash=''){p.layer.append('path').datum(data).attr('d',d3.line().x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',color).attr('stroke-width',2).attr('stroke-dasharray',dash);}
